-- =============================================================================
-- 507_Gyimah_PageAccessMembership.postgres.sql
--
-- GENERATED by scripts/iam/gen-staff-migration-sql.mjs. Regenerate rather than
-- editing by hand. Needs 506_Gyimah_PageAccessCatalog first.
--
-- Staff Page Access becomes per company and enforced from one place:
--
--   1. userfarms.status (active | suspended | terminated) — suspending or
--      terminating someone at one company removes every permission there,
--      whatever is ticked.
--   2. fniam_membership(): owner / active / suspended / terminated / not a member.
--   3. spiam_geteffectivepermissions() rewritten:
--        not a member, suspended or terminated  -> nothing
--        company owner                          -> everything, cannot be denied
--        explicit Deny                          -> denied (beats roles and Admin)
--        explicit Allow / role grant            -> granted
--      Org-wide grants now only reach companies the person is a member of,
--      which closes the "pass another organisation's farmId" hole.
--   4. spiam_pageaccess_set(): the Staff Page Access save — writes only the
--      Allow/Deny exceptions that differ from the person's roles, refuses to
--      grant beyond the caller's own access, and writes a readable history row
--      per change ("View Profit & Loss: Enabled → Disabled").
--   5. spiam_membership_setstatus(): suspend / terminate / reactivate.
--   6. Rebuilds every plain staff member's access per company from what they
--      could actually open before (their saved Staff Page Access ticks run
--      through the rules the menus used), replacing the org-wide rows the
--      earlier migrations carried. Staff admins keep the Organization Admin
--      role. Owners need no rows. Nobody gains or loses a page.
--
-- No business data is touched. To dry-run: replace the final COMMIT with ROLLBACK.
-- =============================================================================

BEGIN;

-- ---- 1. membership status -------------------------------------------------------
ALTER TABLE userfarms ADD COLUMN IF NOT EXISTS status          varchar(12) NOT NULL DEFAULT 'active';
ALTER TABLE userfarms ADD COLUMN IF NOT EXISTS statuschangedat timestamp;
ALTER TABLE userfarms ADD COLUMN IF NOT EXISTS statuschangedby varchar(450);
ALTER TABLE userfarms ADD COLUMN IF NOT EXISTS statusreason    varchar(400);

DO $chk$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_userfarms_status') THEN
        ALTER TABLE userfarms ADD CONSTRAINT ck_userfarms_status
            CHECK (status IN ('active', 'suspended', 'terminated'));
    END IF;
END
$chk$;

-- Staff whose only link to a company was their primary FarmId get a real
-- membership row, so they can be suspended there like anyone else.
SELECT u.id, f.id, 'Staff', (now() at time zone 'utc')
FROM   aspnetusers u
JOIN   farms f ON (f.id = u.farmid OR f.farmid = u.farmid) AND NOT COALESCE(f.isdeleted, FALSE)
WHERE  COALESCE(u.isstaff, FALSE)
  AND  NOT EXISTS (SELECT 1 FROM userfarms uf WHERE uf.userid = u.id AND (uf.farmid = f.id OR uf.farmid = f.farmid))
ON CONFLICT DO NOTHING;

-- ---- 2. membership ------------------------------------------------------------
CREATE OR REPLACE FUNCTION fniam_membership(p_userid text, p_farmid text)
RETURNS text
LANGUAGE plpgsql STABLE
AS $fn$
DECLARE
    v_isstaff boolean;
    v_farm    text;
    v_alt     text;
    v_owner   text;
    v_status  text;
BEGIN
    IF p_userid IS NULL OR p_farmid IS NULL OR p_farmid = '' THEN
        RETURN NULL;
    END IF;

    SELECT COALESCE(u.isstaff, FALSE) INTO v_isstaff FROM aspnetusers u WHERE u.id = p_userid;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- farms.id is the key, but older rows (userfarms, AspNetUsers.FarmId)
    -- may carry the vestigial farms.farmid instead; match either.
    SELECT f.id, COALESCE(NULLIF(f.farmid, ''), f.id), NULLIF(f.owneruserid, '') INTO v_farm, v_alt, v_owner
    FROM   farms f
    WHERE  (f.id = p_farmid OR f.farmid = p_farmid) AND NOT COALESCE(f.isdeleted, FALSE)
    LIMIT 1;
    IF v_farm IS NULL THEN RETURN NULL; END IF;

    IF v_owner = p_userid THEN RETURN 'owner'; END IF;

    SELECT COALESCE(uf.status, 'active') INTO v_status
    FROM   userfarms uf
    WHERE  uf.userid = p_userid AND uf.farmid IN (v_farm, v_alt, p_farmid)
    ORDER BY CASE uf.status WHEN 'active' THEN 0 WHEN 'suspended' THEN 1 ELSE 2 END
    LIMIT 1;

    IF v_status IS NULL AND EXISTS (
        SELECT 1 FROM aspnetusers u WHERE u.id = p_userid AND u.farmid IN (v_farm, v_alt, p_farmid)) THEN
        v_status := 'active';
    END IF;
    IF v_status IS NULL THEN RETURN NULL; END IF;

    -- A non-staff account linked to a company is that company's owner
    -- (subscriber); the multi-company model links owners through userfarms too.
    IF NOT v_isstaff AND v_status = 'active' THEN RETURN 'owner'; END IF;
    RETURN v_status;
END
$fn$;

-- ---- 3. effective permissions --------------------------------------------------
CREATE OR REPLACE FUNCTION spiam_geteffectivepermissions(p_userid text, p_farmid text DEFAULT NULL::text)
RETURNS TABLE(permissionkey text, source text)
LANGUAGE plpgsql
AS $function$
DECLARE
    v_now         timestamp := (now() at time zone 'utc');
    v_member      text;
    v_isstaff     boolean;
    v_issuperuser boolean;
BEGIN
    -- Company-scoped rows are stored against farms.id; accept either id.
    p_farmid := COALESCE((SELECT f.id FROM farms f WHERE f.id = p_farmid OR f.farmid = p_farmid LIMIT 1), p_farmid);

    IF p_farmid IS NOT NULL AND p_farmid <> '' THEN
        v_member := fniam_membership(p_userid, p_farmid);
        -- Not a member, suspended or terminated: nothing, whatever is ticked.
        IF v_member IS NULL OR v_member IN ('suspended', 'terminated') THEN
            RETURN;
        END IF;
        -- The company owner is never restricted.
        IF v_member = 'owner' THEN
            RETURN QUERY SELECT p.permissionkey::text, 'owner'::text FROM iampermissions p;
            RETURN;
        END IF;
    ELSE
        -- No company (Business Office): owners see everything; staff keep
        -- their organisation-wide grants below.
        SELECT COALESCE(u.isstaff, FALSE) INTO v_isstaff FROM aspnetusers u WHERE u.id = p_userid;
        IF v_isstaff = FALSE THEN
            RETURN QUERY SELECT p.permissionkey::text, 'owner'::text FROM iampermissions p;
            RETURN;
        END IF;
    END IF;

    -- Below here the person is an active member (or in the Business Office), so
    -- org-wide rows (farmid NULL) only ever reach their own companies.
    SELECT EXISTS (
        SELECT 1
        FROM iamuserroles ur
        JOIN iamroles r ON r.roleid = ur.roleid
        WHERE ur.userid = p_userid
          AND r.isactive = TRUE
          AND r.issuperuser = TRUE
          AND (ur.expiresat IS NULL OR ur.expiresat > v_now)
          AND (ur.farmid IS NULL OR (p_farmid IS NOT NULL AND ur.farmid = p_farmid))
    ) INTO v_issuperuser;

    IF v_issuperuser THEN
        RETURN QUERY
        WITH denies AS (
            SELECT DISTINCT up.permissionkey AS dkey
            FROM iamuserpermissions up
            WHERE up.userid = p_userid
              AND up.effect = 'Deny'
              AND (up.expiresat IS NULL OR up.expiresat > v_now)
              AND (up.farmid IS NULL OR (p_farmid IS NOT NULL AND up.farmid = p_farmid))
        )
        SELECT p.permissionkey::text, 'superuser'::text
        FROM iampermissions p
        WHERE NOT EXISTS (SELECT 1 FROM denies d WHERE d.dkey = p.permissionkey);
        RETURN;
    END IF;

    RETURN QUERY
    WITH roles AS (
        SELECT DISTINCT r.roleid AS rid, r.name AS rname
        FROM iamuserroles ur
        JOIN iamroles r ON r.roleid = ur.roleid
        WHERE ur.userid = p_userid
          AND r.isactive = TRUE
          AND (ur.expiresat IS NULL OR ur.expiresat > v_now)
          AND (ur.farmid IS NULL OR (p_farmid IS NOT NULL AND ur.farmid = p_farmid))
    ),
    denies AS (
        SELECT DISTINCT up.permissionkey AS dkey
        FROM iamuserpermissions up
        WHERE up.userid = p_userid
          AND up.effect = 'Deny'
          AND (up.expiresat IS NULL OR up.expiresat > v_now)
          AND (up.farmid IS NULL OR (p_farmid IS NOT NULL AND up.farmid = p_farmid))
    ),
    x AS (
        SELECT rp.permissionkey AS xkey, ('role:' || rl.rname)::text AS xsource
        FROM iamrolepermissions rp
        JOIN roles rl ON rl.rid = rp.roleid
        UNION ALL
        SELECT up.permissionkey AS xkey, 'override'::text AS xsource
        FROM iamuserpermissions up
        WHERE up.userid = p_userid
          AND up.effect = 'Allow'
          AND (up.expiresat IS NULL OR up.expiresat > v_now)
          AND (up.farmid IS NULL OR (p_farmid IS NOT NULL AND up.farmid = p_farmid))
    )
    SELECT x.xkey::text, MIN(x.xsource)::text
    FROM x
    WHERE NOT EXISTS (SELECT 1 FROM denies d WHERE d.dkey = x.xkey)
    GROUP BY x.xkey;
END;
$function$;

-- Helper: the module a company's pages live in.
CREATE OR REPLACE FUNCTION fniam_farmmodule(p_farmid text)
RETURNS text
LANGUAGE sql STABLE
AS $fn$
    SELECT CASE lower(trim(f.type))
               WHEN 'poultry' THEN 'poultry' WHEN 'water' THEN 'water' WHEN 'generic' THEN 'generic'
               WHEN 'hotel' THEN 'hotel' WHEN 'restaurant' THEN 'restaurant' WHEN 'livestock' THEN 'livestock'
           END
    FROM farms f WHERE f.id = p_farmid OR f.farmid = p_farmid LIMIT 1
$fn$;

-- ---- 4. the Staff Page Access save -----------------------------------------------
CREATE OR REPLACE FUNCTION spiam_pageaccess_set(
    p_calleruserid text, p_userid text, p_farmid_in text, p_permissionkeys text, p_reason text DEFAULT NULL)
RETURNS TABLE(changed integer)
LANGUAGE plpgsql
AS $fn$
DECLARE
    p_farmid  text := COALESCE((SELECT f.id FROM farms f WHERE f.id = p_farmid_in OR f.farmid = p_farmid_in LIMIT 1), p_farmid_in);
    v_now     timestamp := (now() at time zone 'utc');
    v_module  text := fniam_farmmodule(p_farmid);
    v_caller  text := fniam_membership(p_calleruserid, p_farmid);
    v_target  text := fniam_membership(p_userid, p_farmid);
    v_beyond  text;
    v_changed integer;
BEGIN
    IF v_module IS NULL THEN
        RAISE EXCEPTION 'Company not found.' USING ERRCODE = 'P0001';
    END IF;
    IF p_userid = p_calleruserid THEN
        RAISE EXCEPTION 'You cannot change your own page access.' USING ERRCODE = 'P0001';
    END IF;
    IF v_target IS NULL THEN
        RAISE EXCEPTION 'This person is not a member of this company.' USING ERRCODE = 'P0001';
    END IF;
    IF v_target = 'owner' THEN
        RAISE EXCEPTION 'The company owner always has full access and cannot be restricted.' USING ERRCODE = 'P0001';
    END IF;
    IF v_caller IS DISTINCT FROM 'owner' AND NOT EXISTS (
        SELECT 1 FROM spiam_geteffectivepermissions(p_calleruserid, p_farmid) e
        WHERE e.permissionkey = 'office.employee-access.edit') THEN
        RAISE EXCEPTION 'Forbidden: you need Manage Employee Access to change page access.' USING ERRCODE = '42501';
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _pa_scope (k text PRIMARY KEY, label text) ON COMMIT DROP;
    CREATE TEMP TABLE IF NOT EXISTS _pa_want  (k text PRIMARY KEY) ON COMMIT DROP;
    CREATE TEMP TABLE IF NOT EXISTS _pa_role  (k text PRIMARY KEY) ON COMMIT DROP;
    CREATE TEMP TABLE IF NOT EXISTS _pa_before (k text PRIMARY KEY) ON COMMIT DROP;
    TRUNCATE _pa_scope, _pa_want, _pa_role, _pa_before;

    -- Only this company's module and the shared office keys are in scope.
    SELECT p.permissionkey, p.resourcelabel || CASE p.action WHEN 'view' THEN '' ELSE ' — ' || initcap(p.action) END
    FROM iampermissions p WHERE p.module IN (v_module, 'office');

    SELECT DISTINCT btrim(k) FROM unnest(string_to_array(COALESCE(p_permissionkeys, ''), ',')) AS k
    WHERE btrim(k) IN (SELECT s.k FROM _pa_scope s);

    SELECT e.permissionkey FROM spiam_geteffectivepermissions(p_userid, p_farmid) e
    WHERE e.permissionkey IN (SELECT s.k FROM _pa_scope s);

    -- Nobody hands out access they do not hold themselves (owners hold everything).
    IF v_caller IS DISTINCT FROM 'owner' THEN
        SELECT string_agg(w.k, ', ') INTO v_beyond
        FROM _pa_want w
        WHERE w.k NOT IN (SELECT b.k FROM _pa_before b)
          AND w.k NOT IN (SELECT e.permissionkey FROM spiam_geteffectivepermissions(p_calleruserid, p_farmid) e);
        IF v_beyond IS NOT NULL THEN
            RAISE EXCEPTION 'Forbidden: you cannot grant access you do not have yourself (%).', v_beyond USING ERRCODE = '42501';
        END IF;
    END IF;

    -- What the person's roles give in this company, before any exception.
    SELECT DISTINCT rp.permissionkey
    FROM iamuserroles ur
    JOIN iamroles r ON r.roleid = ur.roleid AND r.isactive
    JOIN iamrolepermissions rp ON rp.roleid = r.roleid
    WHERE ur.userid = p_userid
      AND (ur.expiresat IS NULL OR ur.expiresat > v_now)
      AND (ur.farmid IS NULL OR ur.farmid = p_farmid)
      AND rp.permissionkey IN (SELECT s.k FROM _pa_scope s)
    UNION
    SELECT s.k FROM _pa_scope s
    WHERE EXISTS (SELECT 1 FROM iamuserroles ur JOIN iamroles r ON r.roleid = ur.roleid AND r.isactive AND r.issuperuser
                  WHERE ur.userid = p_userid AND (ur.expiresat IS NULL OR ur.expiresat > v_now)
                    AND (ur.farmid IS NULL OR ur.farmid = p_farmid))
    ON CONFLICT DO NOTHING;

    -- Replace this company's exceptions with exactly the ones that differ from the roles.
    DELETE FROM iamuserpermissions up
    WHERE up.userid = p_userid AND up.farmid = p_farmid
      AND up.permissionkey IN (SELECT s.k FROM _pa_scope s);

    SELECT p_userid, p_farmid, w.k, 'Allow', COALESCE(NULLIF(p_reason, ''), 'Staff Page Access'), p_calleruserid, v_now
    FROM _pa_want w WHERE w.k NOT IN (SELECT r.k FROM _pa_role r)
    UNION ALL
    SELECT p_userid, p_farmid, r.k, 'Deny', COALESCE(NULLIF(p_reason, ''), 'Staff Page Access'), p_calleruserid, v_now
    FROM _pa_role r WHERE r.k NOT IN (SELECT w.k FROM _pa_want w);

    -- Readable history: one row per page or action that actually changed.
    SELECT 'PageAccess', CASE WHEN w.k IS NULL THEN 'Revoke' ELSE 'Grant' END,
           p_userid, p_calleruserid, p_farmid,
           left(s.label || ': ' || CASE WHEN w.k IS NULL THEN 'Enabled → Disabled' ELSE 'Disabled → Enabled' END
                || CASE WHEN NULLIF(p_reason, '') IS NOT NULL THEN ' (' || p_reason || ')' ELSE '' END, 400)
    FROM _pa_scope s
    LEFT JOIN _pa_want w ON w.k = s.k
    LEFT JOIN _pa_before b ON b.k = s.k
    WHERE (w.k IS NULL) <> (b.k IS NULL);
    GET DIAGNOSTICS v_changed = ROW_COUNT;

    -- Mirror onto the legacy flags for the person's main company, for older
    -- clients that still read AspNetUsers.FeaturePermissions. Never read for access.
    UPDATE aspnetusers u
    SET featurepermissions = (
        COALESCE(NULLIF(u.featurepermissions, '')::jsonb, '{}'::jsonb) || jsonb_build_object(
            'canEnterSales',      EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.sales.view'),
            'canEnterExpenses',   EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.expenses.view'),
            'canViewCashLedger',  EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.cash.view'),
            'canViewFinancial',   EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.profit-loss.view'),
            'canViewReports',     EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.reports.view'),
            'canViewCustomers',   EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.customers.view'),
            'canSeeEmployees',    EXISTS (SELECT 1 FROM _pa_want WHERE k = 'office.employees.view'),
            'canViewActivityLog', EXISTS (SELECT 1 FROM _pa_want WHERE k = 'office.audit-log.view'),
            'canViewSettings',    EXISTS (SELECT 1 FROM _pa_want WHERE k = v_module || '.setup.view')
        ))::text
    WHERE u.id = p_userid
      AND (u.farmid = p_farmid OR u.farmid IN (SELECT f.farmid FROM farms f WHERE f.id = p_farmid))
      AND (u.featurepermissions IS NULL OR u.featurepermissions = '' OR left(btrim(u.featurepermissions), 1) = '{');

    RETURN QUERY SELECT v_changed;
END
$fn$;

-- ---- 5. suspend / terminate / reactivate --------------------------------------------
CREATE OR REPLACE FUNCTION spiam_membership_setstatus(
    p_calleruserid text, p_userid text, p_farmid text, p_status text, p_reason text DEFAULT NULL)
RETURNS TABLE(status text)
LANGUAGE plpgsql
AS $fn$
DECLARE
    v_now    timestamp := (now() at time zone 'utc');
    v_caller text := fniam_membership(p_calleruserid, p_farmid);
    v_target text := fniam_membership(p_userid, p_farmid);
    v_farm   text;
BEGIN
    IF p_status NOT IN ('active', 'suspended', 'terminated') THEN
        RAISE EXCEPTION 'Status must be active, suspended or terminated.' USING ERRCODE = 'P0001';
    END IF;
    IF p_userid = p_calleruserid THEN
        RAISE EXCEPTION 'You cannot change your own status.' USING ERRCODE = 'P0001';
    END IF;
    IF v_target IS NULL THEN
        RAISE EXCEPTION 'This person is not a member of this company.' USING ERRCODE = 'P0001';
    END IF;
    IF v_target = 'owner' THEN
        RAISE EXCEPTION 'The company owner cannot be suspended or terminated.' USING ERRCODE = 'P0001';
    END IF;
    IF v_caller IS DISTINCT FROM 'owner' AND NOT EXISTS (
        SELECT 1 FROM spiam_geteffectivepermissions(p_calleruserid, p_farmid) e
        WHERE e.permissionkey = 'office.employee-status.edit') THEN
        RAISE EXCEPTION 'Forbidden: you need Suspend or Terminate Employee to do this.' USING ERRCODE = '42501';
    END IF;

    SELECT f.id INTO v_farm FROM farms f WHERE f.id = p_farmid OR f.farmid = p_farmid LIMIT 1;

    UPDATE userfarms uf
    SET    status = p_status, statuschangedat = v_now, statuschangedby = p_calleruserid, statusreason = p_reason
    WHERE  uf.userid = p_userid
      AND  uf.farmid IN (SELECT f.id FROM farms f WHERE f.id = v_farm
                         UNION SELECT f.farmid FROM farms f WHERE f.id = v_farm AND f.farmid IS NOT NULL);
    IF NOT FOUND THEN
        VALUES (p_userid, v_farm, 'Staff', v_now, p_status, v_now, p_calleruserid, p_reason);
    END IF;

    -- No active company left: end every session at once (the token watermark).
    IF p_status <> 'active' AND to_regclass('public.iamusersecurity') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM userfarms uf WHERE uf.userid = p_userid AND uf.status = 'active') THEN
        VALUES (p_userid, v_now, v_now, p_calleruserid)
        ON CONFLICT (userid) DO UPDATE SET tokensvalidfrom = v_now, updatedat = v_now, updatedby = p_calleruserid;
    END IF;

    VALUES ('Membership', initcap(p_status), p_userid, p_calleruserid, v_farm,
            left('Status changed to ' || p_status || COALESCE(' (' || NULLIF(p_reason, '') || ')', ''), 400));

    RETURN QUERY SELECT p_status::text;
END
$fn$;

CREATE OR REPLACE FUNCTION spiam_getmemberships(p_userid text)
RETURNS TABLE(farmid text, farmname text, farmtype text, status text, statuschangedat timestamp, statusreason text)
LANGUAGE sql STABLE
AS $fn$
    SELECT f.id::text, f.name::text, f.type::text, COALESCE(uf.status, 'active')::text, uf.statuschangedat, uf.statusreason::text
    FROM userfarms uf
    JOIN farms f ON (f.id = uf.farmid OR f.farmid = uf.farmid) AND NOT COALESCE(f.isdeleted, FALSE)
    WHERE uf.userid = p_userid
    ORDER BY f.name
$fn$;

-- ---- 5a. revocation also ends refresh tokens ------------------------------------------
-- "Sign out everywhere" and losing the last active company stamp
-- iamusersecurity.tokensvalidfrom. The Farm API rejects access tokens issued
-- before it (now that tokens carry iat); clearing the stored refresh token
-- stops the browser from simply renewing one.
CREATE OR REPLACE FUNCTION triamusersecurity_endrefresh_fn()
RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
    IF NEW.tokensvalidfrom IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.tokensvalidfrom END) THEN
        UPDATE aspnetusers SET refreshtoken = NULL, refreshtokenexpiry = (now() at time zone 'utc')
        WHERE id = NEW.userid;
    END IF;
    RETURN NEW;
END
$fn$;

DROP TRIGGER IF EXISTS triamusersecurity_endrefresh ON iamusersecurity;
CREATE TRIGGER triamusersecurity_endrefresh
AFTER INSERT OR UPDATE OF tokensvalidfrom ON iamusersecurity
FOR EACH ROW EXECUTE FUNCTION triamusersecurity_endrefresh_fn();

-- ---- 5c. "Grant administrator access" has one meaning ------------------------------
-- The switch on Edit Employee writes AspNetUsers.IsAdmin (Login API). Keep the
-- Organization Admin role in step with it, so an admin is an admin in exactly
-- one way — and an owner can still untick a page for them (an explicit Deny
-- beats the role).
CREATE OR REPLACE FUNCTION traspnetusers_adminrole_fn()
RETURNS trigger
LANGUAGE plpgsql
AS $fn$
DECLARE
    v_role int := (SELECT roleid FROM iamroles WHERE rolekey = 'sys-org-admin');
BEGIN
    IF v_role IS NULL OR NOT COALESCE(NEW.isstaff, FALSE) THEN RETURN NEW; END IF;
    IF COALESCE(NEW.isadmin, FALSE) THEN
        SELECT NEW.id, v_role, NULL, NULL, (now() at time zone 'utc')
        WHERE NOT EXISTS (SELECT 1 FROM iamuserroles x WHERE x.userid = NEW.id AND x.roleid = v_role AND x.farmid IS NULL);
    ELSE
        DELETE FROM iamuserroles x WHERE x.userid = NEW.id AND x.roleid = v_role AND x.farmid IS NULL;
    END IF;
    RETURN NEW;
END
$fn$;

DROP TRIGGER IF EXISTS traspnetusers_adminrole ON aspnetusers;
CREATE TRIGGER traspnetusers_adminrole
AFTER INSERT OR UPDATE OF isadmin ON aspnetusers
FOR EACH ROW EXECUTE FUNCTION traspnetusers_adminrole_fn();

-- ---- 5b. who may manage an employee (Login API: Admin/employees/*) -------------------
-- The caller and the target must be in the same organisation, the target must
-- not be the organisation owner, and the caller must be that owner, a staff
-- admin, or hold the matching office.* key in a company the target belongs to.
CREATE OR REPLACE FUNCTION fniam_maymanageemployee(p_calleruserid text, p_targetuserid text, p_permissionkey text DEFAULT 'office.employees.edit')
RETURNS boolean
LANGUAGE plpgsql STABLE
AS $fn$
DECLARE
    v_org_caller text := fniam_orgowner(p_calleruserid);
    v_org_target text := fniam_orgowner(p_targetuserid);
    v_isstaff    boolean;
    v_isadmin    boolean;
BEGIN
    IF p_calleruserid IS NULL OR p_targetuserid IS NULL THEN RETURN FALSE; END IF;
    IF p_calleruserid = p_targetuserid THEN RETURN FALSE; END IF;
    IF v_org_caller IS NULL OR v_org_caller IS DISTINCT FROM v_org_target THEN RETURN FALSE; END IF;
    -- Nobody manages the owner's own account through the employee screens.
    IF p_targetuserid = v_org_target THEN RETURN FALSE; END IF;

    SELECT COALESCE(u.isstaff, FALSE), COALESCE(u.isadmin, FALSE) INTO v_isstaff, v_isadmin
    FROM aspnetusers u WHERE u.id = p_calleruserid;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF NOT v_isstaff THEN RETURN TRUE; END IF;      -- the organisation owner
    IF v_isadmin THEN RETURN TRUE; END IF;          -- staff admin (Grant Administrator Access)

    -- Otherwise the explicit permission, in any company the target works in.
    RETURN EXISTS (
        SELECT 1
        FROM userfarms uf
        JOIN farms f ON (f.id = uf.farmid OR f.farmid = uf.farmid)
        CROSS JOIN LATERAL spiam_geteffectivepermissions(p_calleruserid, f.id) e
        WHERE uf.userid = p_targetuserid
          AND e.permissionkey = p_permissionkey);
END
$fn$;

-- ---- 6. rebuild existing staff access per company ------------------------------------
CREATE TEMP TABLE _rules (module text, resource text, kind text, flags text[], actions text[]) ON COMMIT DROP;

CREATE TEMP TABLE _flagmap (flag text, permissionkey text) ON COMMIT DROP;

CREATE TEMP TABLE _aliases (flag text, names text[]) ON COMMIT DROP;

CREATE TEMP TABLE _waterflags (flag text) ON COMMIT DROP;

-- First defined alias wins, as lib/api/auth.ts read them.
CREATE FUNCTION pg_temp.flagvalue(j jsonb, names text[]) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $f$
DECLARE n text; v text;
BEGIN
    IF j IS NULL OR jsonb_typeof(j) <> 'object' THEN RETURN NULL; END IF;
    FOREACH n IN ARRAY names LOOP
        IF j ? n THEN
            v := lower(j ->> n);
            IF v IN ('true', '1', 'yes') THEN RETURN TRUE; END IF;
            IF v IN ('false', '0', 'no') THEN RETURN FALSE; END IF;
        END IF;
    END LOOP;
    RETURN NULL;
END $f$;

CREATE FUNCTION pg_temp.tryjson(t text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $f$
BEGIN
    RETURN t::jsonb;
EXCEPTION WHEN others THEN
    RETURN NULL;
END $f$;

-- Plain staff (not admins) and every company they belong to.
CREATE TEMP TABLE _staff ON COMMIT DROP AS
SELECT u.id AS userid, f.id AS farmid, fniam_farmmodule(f.id) AS module,
       pg_temp.tryjson(NULLIF(u.featurepermissions, '')) AS j
FROM   aspnetusers u
JOIN   userfarms uf ON uf.userid = u.id
JOIN   farms f ON (f.id = uf.farmid OR f.farmid = uf.farmid) AND NOT COALESCE(f.isdeleted, FALSE)
WHERE  COALESCE(u.isstaff, FALSE) AND NOT COALESCE(u.isadmin, FALSE)
  AND  NULLIF(f.owneruserid, '') IS DISTINCT FROM u.id
  AND  fniam_farmmodule(f.id) IS NOT NULL;

-- Flags each person held (water flags were on for every staff member).
CREATE TEMP TABLE _held ON COMMIT DROP AS
SELECT DISTINCT s.userid, a.flag
FROM _staff s CROSS JOIN _aliases a
WHERE pg_temp.flagvalue(s.j, a.names) IS TRUE
UNION
SELECT DISTINCT s.userid, w.flag FROM _staff s CROSS JOIN _waterflags w;

-- What can() answered before: the flag map, plus their own (org-wide or
-- company) Allow rows, minus Denies.
CREATE TEMP TABLE _oldcan ON COMMIT DROP AS
SELECT DISTINCT s.userid, s.farmid, k.permissionkey
FROM _staff s
JOIN LATERAL (
    SELECT m.permissionkey FROM _held h JOIN _flagmap m ON m.flag = h.flag WHERE h.userid = s.userid
    UNION
    SELECT up.permissionkey FROM iamuserpermissions up
    WHERE up.userid = s.userid AND up.effect = 'Allow' AND (up.farmid IS NULL OR up.farmid = s.farmid)
      AND (up.expiresat IS NULL OR up.expiresat > (now() at time zone 'utc'))
) k ON TRUE
WHERE NOT EXISTS (SELECT 1 FROM iamuserpermissions d
                  WHERE d.userid = s.userid AND d.effect = 'Deny' AND d.permissionkey = k.permissionkey
                    AND (d.farmid IS NULL OR d.farmid = s.farmid));

-- The page views each person could open in each company.
CREATE TEMP TABLE _views ON COMMIT DROP AS
SELECT s.userid, s.farmid, r.module, r.resource, r.actions
FROM _staff s
JOIN _rules r ON r.module IN (s.module, 'office')
WHERE CASE r.kind
        WHEN 'always' THEN TRUE
        WHEN 'admin'  THEN FALSE
        WHEN 'iam'    THEN EXISTS (SELECT 1 FROM _oldcan o WHERE o.userid = s.userid AND o.farmid = s.farmid
                                    AND o.permissionkey = r.module || '.' || r.resource || '.view')
        ELSE EXISTS (SELECT 1 FROM _held h WHERE h.userid = s.userid AND h.flag = ANY (r.flags))
      END;

CREATE TEMP TABLE _grants ON COMMIT DROP AS
-- the page itself, and the everyday actions every staff member had on it
SELECT v.userid, v.farmid, v.module || '.' || v.resource || '.' || a AS permissionkey
FROM _views v CROSS JOIN LATERAL unnest(ARRAY['view'] || v.actions) AS a
UNION
-- finer actions can() already answered yes to, on pages they can open or on
-- keys that are not pages at all
SELECT o.userid, o.farmid, o.permissionkey
FROM _oldcan o
JOIN iampermissions p ON p.permissionkey = o.permissionkey
JOIN _staff s ON s.userid = o.userid AND s.farmid = o.farmid AND p.module IN (s.module, 'office')
WHERE p.action <> 'view'
  AND (EXISTS (SELECT 1 FROM _views v WHERE v.userid = o.userid AND v.farmid = o.farmid
                AND v.module = p.module AND v.resource = p.resource)
       OR NOT EXISTS (SELECT 1 FROM _rules r WHERE r.module = p.module AND r.resource = p.resource));

DO $rebuild$
DECLARE
    v_staff   int;
    v_before  int;
    v_after   int;
    v_admins  int := 0;
    v_sens    int;
    rec       record;
BEGIN
    SELECT count(DISTINCT userid) INTO v_staff FROM _staff;
    SELECT count(*) INTO v_before FROM iamuserpermissions up WHERE up.userid IN (SELECT userid FROM _staff);

    -- Old rows for these people (all carried by earlier migrations, org-wide)
    -- are replaced by the per-company set; Denies are kept per company.
    SELECT DISTINCT s.userid, s.farmid, d.permissionkey, 'Deny', d.reason, d.grantedby, d.grantedat
    FROM iamuserpermissions d
    JOIN _staff s ON s.userid = d.userid
    JOIN iampermissions p ON p.permissionkey = d.permissionkey AND p.module IN (s.module, 'office')
    WHERE d.effect = 'Deny' AND d.farmid IS NULL
    ON CONFLICT (userid, farmid, permissionkey) DO NOTHING;

    DELETE FROM iamuserpermissions up
    WHERE up.userid IN (SELECT userid FROM _staff) AND (up.farmid IS NULL OR up.effect = 'Allow');

    SELECT g.userid, g.farmid, g.permissionkey, 'Allow',
           'Staff page access before migration 507', NULL, (now() at time zone 'utc')
    FROM _grants g
    WHERE EXISTS (SELECT 1 FROM iampermissions p WHERE p.permissionkey = g.permissionkey)
      AND NOT EXISTS (SELECT 1 FROM iamuserpermissions d WHERE d.userid = g.userid AND d.farmid = g.farmid
                        AND d.permissionkey = g.permissionkey)
    ON CONFLICT (userid, farmid, permissionkey) DO NOTHING;

    SELECT count(*) INTO v_after FROM iamuserpermissions up WHERE up.userid IN (SELECT userid FROM _staff);

    -- Staff admins saw every page before; make sure each holds Organization Admin.
    SELECT u.id, r.roleid, NULL, NULL, (now() at time zone 'utc')
    FROM aspnetusers u CROSS JOIN iamroles r
    WHERE COALESCE(u.isstaff, FALSE) AND COALESCE(u.isadmin, FALSE) AND r.rolekey = 'sys-org-admin'
      AND NOT EXISTS (SELECT 1 FROM iamuserroles x WHERE x.userid = u.id AND x.roleid = r.roleid)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_admins = ROW_COUNT;

    RAISE NOTICE '507: % staff rebuilt per company (% rows before, % after); % staff admin(s) given Organization Admin.',
        v_staff, v_before, v_after, v_admins;

    -- Per-person report: pages per company, and sensitive pages they KEEP
    -- because they could already open them (owners may want to review these).
    FOR rec IN
        SELECT u.username, f.name AS company, count(*) FILTER (WHERE p.action = 'view') AS pages,
               string_agg(p.resourcelabel, ', ' ORDER BY p.resourcelabel)
                   FILTER (WHERE p.action = 'view' AND p.defaultgrant = 'sensitive') AS sensitive
        FROM iamuserpermissions up
        JOIN aspnetusers u ON u.id = up.userid
        JOIN farms f ON f.id = up.farmid
        JOIN iampermissions p ON p.permissionkey = up.permissionkey
        WHERE up.userid IN (SELECT userid FROM _staff) AND up.effect = 'Allow'
        GROUP BY u.username, f.name
        ORDER BY u.username, f.name
    LOOP
        RAISE NOTICE '507:   % @ % — % page(s)%', rec.username, rec.company, rec.pages,
            COALESCE('; keeps sensitive: ' || rec.sensitive, '');
    END LOOP;

    SELECT count(*) INTO v_sens FROM _staff s
    WHERE NOT EXISTS (SELECT 1 FROM iamuserpermissions up WHERE up.userid = s.userid AND up.farmid = s.farmid
                      AND up.effect = 'Allow' AND up.permissionkey LIKE '%.view');
    IF v_sens > 0 THEN
        RAISE NOTICE '507: % staff membership(s) have no pages at all (same as before — their menus were empty too).', v_sens;
    END IF;
END
$rebuild$;

-- ---- self-test ----------------------------------------------------------------------
DO $test$
DECLARE
    v_owner text; v_farm text; v_n int;
BEGIN
    -- An owner gets the whole catalog for their own company...
    SELECT f.owneruserid, f.id INTO v_owner, v_farm FROM farms f
    WHERE NULLIF(f.owneruserid, '') IS NOT NULL AND NOT COALESCE(f.isdeleted, FALSE) LIMIT 1;
    IF v_owner IS NOT NULL THEN
        SELECT count(*) INTO v_n FROM spiam_geteffectivepermissions(v_owner, v_farm);
        IF v_n <> (SELECT count(*) FROM iampermissions) THEN
            RAISE EXCEPTION '507 self-test: owner sees % of % keys.', v_n, (SELECT count(*) FROM iampermissions);
        END IF;
        -- ...and nothing in a company they are not a member of.
        SELECT count(*) INTO v_n FROM spiam_geteffectivepermissions(v_owner,
            (SELECT f.id FROM farms f WHERE NULLIF(f.owneruserid, '') IS DISTINCT FROM v_owner
               AND fniam_membership(v_owner, f.id) IS NULL LIMIT 1));
        IF v_n <> 0 THEN
            RAISE EXCEPTION '507 self-test: an owner reached another organisation''s company (% keys).', v_n;
        END IF;
    END IF;

    -- No rebuilt staff member may be left with an org-wide row.
    IF EXISTS (SELECT 1 FROM iamuserpermissions up
               WHERE up.farmid IS NULL AND up.userid IN (SELECT userid FROM _staff)) THEN
        RAISE EXCEPTION '507 self-test: org-wide staff rows remain.';
    END IF;

    RAISE NOTICE '507 self-test passed.';
END
$test$;

COMMIT;
